import re

records = [
    {"email": "ana@example.com", "status": "active", "age": 34},
    {"email": "bad-email", "status": "active", "age": 28},
    {"email": "luis@example.com", "status": "unknown", "age": -1},
    {"email": "sofia@example.com", "status": "inactive", "age": 41},
]

EMAIL_RE = re.compile(r"^[\w.\-]+@[\w.\-]+\.\w+$")
VALID_STATUS = {"active", "inactive"}

def validate(record):
    problems = []
    if not EMAIL_RE.match(record["email"]):
        problems.append("email invalido")
    if record["status"] not in VALID_STATUS:
        problems.append("status desconocido")
    if record["age"] <= 0:
        problems.append("edad invalida")
    return problems

quarantine = []
clean = []
for r in records:
    problems = validate(r)
    if problems:
        quarantine.append((r["email"], problems))
    else:
        clean.append(r)

print(f"registros validos: {len(clean)}")
print(f"registros en cuarentena: {len(quarantine)}")
for email, problems in quarantine:
    print(f"{email}: {', '.join(problems)}")
